import { createDenoAdapter, type DenoApplication } from '@cossackframework/deno-adapter';

const runtime = createDenoAdapter({ env: { REGION: 'configured', MODE: 'default' }, assetsRoot: './missing-assets' });
const app: DenoApplication = {
  async fetch(_request, env = {}) {
    return Response.json({ region: env.REGION, mode: env.MODE, requestOnly: env.REQUEST_ONLY });
  },
};
const response = await runtime.fetch(app, new Request('http://localhost/data'), {
  REGION: 'request', REQUEST_ONLY: 'yes',
});
const result = await response.json() as Record<string, unknown>;
if (result.region !== 'request' || result.mode !== 'default' || result.requestOnly !== 'yes') {
  throw new Error('Request bindings should override adapter defaults while retaining other defaults');
}
await runtime.dispose();

import { cossackDeno } from '@cossackframework/deno-adapter/vite';

const plugin = cossackDeno({ entry: '/src/index.ts', startupTimeoutMs: 10_000, shutdownTimeoutMs: 1_500 });
if (plugin.name !== 'cossack-deno-development' || plugin.apply !== 'serve') {
  throw new Error('The Deno adapter plugin is a Vite development-only integration');
}
